import { useState } from 'react';

export function ScoreBoard() {
  const [home, setHome] = useState(0);
  const [away, setAway] = useState(0);

  const addHome = (points) => setHome((h) => h + points);
  const addAway = (points) => setAway((a) => a + points);
  const leader = home === away ? 'Remis' : home > away ? 'Gospodarze' : 'Goście';

  return (
    <section className="scoreboard">
      <h2>Prowadzi: {leader}</h2>
      <p className="scoreboard__result">{home} : {away}</p>
      <div>
        {[1, 2, 3].map((p) => (
          <button key={p} type="button" onClick={() => addHome(p)}>Gospodarze +{p}</button>
        ))}
        <button type="button" onClick={() => { addHome(3); addHome(1); }}>Rzut za trzy i faul</button>
      </div>
      <div>
        {[1, 2, 3].map((p) => (
          <button key={p} type="button" onClick={() => addAway(p)}>Goście +{p}</button>
        ))}
        <button type="button" onClick={() => { addAway(3); addAway(1); }}>Rzut za trzy i faul</button>
      </div>
    </section>
  );
}

